(async()=>{const out={};for(const start of [0,.4,.6,1.4,1.6]){const c=new OfflineAudioContext(1,8,8000),b=c.createBuffer(1,3,8000),a=b.getChannelData(0),s=c.createBufferSource();a.set([1,2,3]);s.buffer=b;s.connect(c.destination);s.start(start/8000);a[0]=9;const r=await c.startRendering();out[start]=Array.from(r.getChannelData(0))}const c=new OfflineAudioContext(1,8,8000),events=[];c.onstatechange=()=>events.push('state:'+c.state);c.oncomplete=()=>events.push('complete');const p=c.startRendering();events.push(c.state);await p;events.push('promise');await new Promise(r=>setTimeout(r,20));out.events=events;return out})()
